CREATE TABLE execution_outbox(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,work_id TEXT NOT NULL,message_id TEXT NOT NULL,recipient_id TEXT NOT NULL,connection_id TEXT NOT NULL,actor_id TEXT NOT NULL,state TEXT NOT NULL,provider_message_id TEXT,dedup_key TEXT NOT NULL,next_attempt_at TEXT NOT NULL,created_at TEXT NOT NULL,UNIQUE(workspace_id,dedup_key));
CREATE TABLE execution_delivery_events(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,outbox_id TEXT NOT NULL,provider_event_id TEXT NOT NULL,event TEXT NOT NULL,created_at TEXT NOT NULL,UNIQUE(workspace_id,provider_event_id));
